def gen(rng):
    printable = [chr(c) for c in range(33, 127)]
    def rnd(n, alpha):
        return ''.join(rng.choice(alpha) for _ in range(n))
    tests = ['a', 'aaaaaaa', 'abc', 'abab', 'zyxzyx', 'Aa', 'aAaA', '#!#!x', '~', '0011223344']
    for n in (3, 5, 8, 12, 20, 40):
        for alpha in (printable[:3], printable[:6], printable):
            tests.append(rnd(n, alpha))
    tests.append(rnd(100000, printable))
    tests.append('a' * 100000)
    tests.append(rnd(100000, printable[:2]))
    tests.append((''.join(printable) * 1100)[:100000])
    return tests
